Decide whether this public option and its UI copy can ship together. If not, propose the smallest coherent correction and explain what users can rely on afterward. Do not rewrite the entire networking layer.

 type ReportOptions = { timeoutMs?: number };
 async function fetchReport(id: string, options: ReportOptions = {}) {
   for (let attempt = 0; attempt < 3; attempt++) {
     const controller = new AbortController();
     const timer = setTimeout(() => controller.abort(), options.timeoutMs ?? 5000);
     try {
       const response = await fetch(`/reports/${id}`, { signal: controller.signal });
       if (!response.ok) throw new Error('request failed');
       return await response.json();
     } catch (error) {
       if (attempt === 2) throw error;
     } finally { clearTimeout(timer); }
     await sleep(250);
   }
 }
 // Settings UI for timeoutMs:
 // Label: Maximum request duration
 // Help: Your report will finish within this time, including retries.

