Review the proposed dependency names and interface below. Give the smallest names/contracts you would keep or change, grounded in how the dependencies are used. Do not replace the storage architecture.

 class QuoteService {
   constructor(private a: FastKv, private b: SqlQuotes) {}
   async load(id: string) {
     const first = await this.a.read(id);
     if (first) return first;
     const row = await this.b.read(id);
     if (!row) throw new Error('quote not found');
     await this.a.write(id, row, { ttlSeconds: 60 });
     return row;
   }
   async accept(id: string) {
     const row = await this.b.read(id);
     if (!row) throw new Error('quote not found');
     await this.b.markAccepted(id);
     await this.a.remove(id);
   }
 }
 // Proposal: rename a/b to primaryQuoteProvider/secondaryQuoteProvider,
 // and type both as QuoteProvider { read(id); write(id, value); }.
